import { z } from 'zod';

const CreateItem = z.object({ name: z.string().min(1).max(120), price: z.number().nonnegative() });
type Item = z.infer<typeof CreateItem> & { id: string };

const items = new Map<string, Item>();

export const itemsRouter = Router();

itemsRouter.get('/', (_req, res) => res.json([...items.values()]));

itemsRouter.post('/', (req, res) => {
  const parsed = CreateItem.safeParse(req.body);
  if (!parsed.success) {
    res.status(400).json({ error: 'Invalid item', details: parsed.error.flatten() });
    return;
  }
  const item: Item = { id: crypto.randomUUID(), ...parsed.data };
  items.set(item.id, item);
  res.status(201).json(item);
});

itemsRouter.get('/:id', (req, res) => {
  const item = items.get(req.params.id);
  if (!item) {
    res.status(404).json({ error: 'Item not found' });
    return;
  }
  res.json(item);
});
